/// A connected TCP socket, served on the channel `network.connect` hands back as a
/// capability: send bytes (passed zero-copy as a `buffer` - a shared-memory handle,
/// so the payload never crosses the channel), receive incoming bytes as a
/// wait-drained event stream of chunks (the producer closes when the peer closes -
/// end of stream), and close. The socket is the canonical object; each net tool asks
/// NetworkService for the socket it needs and talks this contract.
// interface `socket` over a channel: opcodes, a Service trait + dispatch, and a Client.
pub mod socket {
	use super::*;
	use crate::codec::{Reader, Sink, SliceWriter, Transport, TransportError, VecWriter};
	use alloc::vec::Vec;

	pub const OP_SEND: u16 = 1;
	pub const OP_RECV: u16 = 2;
	pub const OP_CLOSE: u16 = 3;

	pub trait Service {
		fn send(&mut self, data: crate::codec::Buffer) -> Result<u32, Error>;
		fn recv(&mut self) -> Vec<Chunk>;
		fn close(&mut self) -> Result<(), Error>;
	}

	pub fn dispatch<S: Service>(service: &mut S, request: &[u8], request_handles: &mut Handles, out: &mut [u8], reply_handles: &mut Handles) -> Option<usize> {
		let mut reader = Reader::with_handle_list(request, request_handles);
		let r = &mut reader;
		let op = r.u16()?;
		let corr = r.u32()?;
		let mut writer = SliceWriter::new(out);
		if op == PROTOCOL_INFO_OP {
			r.finish()?;
			request_handles.clear();
			let w = &mut writer;
			w.u32(corr)?;
			w.bytes_lp(b"liber:network")?;
			w.u32(1)?;
			match Handles::try_from_slice(writer.handles()) {
				Some(taken) => *reply_handles = taken,
				None => return None,
			}
			return Some(writer.pos());
		}
		match op {
			OP_SEND => {
				let data = {
					let len = r.u64()?;
					let handle = r.take_handle()?;
					crate::codec::Buffer { handle, len }
				};
				r.finish()?;
				request_handles.clear();
				let result = service.send(data);
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v58) => {
							w.u8(1)?;
							w.u32(*v58)?;
						}
						Err(v59) => {
							w.u8(0)?;
							v59.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			OP_CLOSE => {
				r.finish()?;
				request_handles.clear();
				let result = service.close();
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v60) => {
							w.u8(1)?;
						}
						Err(v61) => {
							w.u8(0)?;
							v61.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			_ => return None,
		}
		match Handles::try_from_slice(writer.handles()) {
			Some(taken) => *reply_handles = taken,
			None => return None,
		}
		Some(writer.pos())
	}

	pub fn recv_open<S: Service>(service: &mut S, request: &[u8], request_handles: &mut Handles) -> Option<(u32, Vec<Chunk>)> {
		let mut reader = Reader::with_handle_list(request, request_handles);
		let r = &mut reader;
		let _op = r.u16()?;
		let corr = r.u32()?;
		r.finish()?;
		request_handles.clear();
		let items = service.recv();
		Some((corr, items))
	}
	pub fn recv_frame(seq: u32, item: &Chunk, out: &mut [u8], frame_handles: &mut Handles) -> Option<usize> {
		let mut writer = SliceWriter::new(out);
		let encoded: Option<()> = (|| {
			let w = &mut writer;
			w.u32(seq)?;
			item.write(w)?;
			Some(())
		})();
		if encoded.is_none() {
			if let Some(taken) = Handles::try_from_slice(writer.handles()) {
				*frame_handles = taken;
			}
			return None;
		}
		*frame_handles = Handles::try_from_slice(writer.handles())?;
		Some(writer.pos())
	}
	pub fn recv_read(msg: &[u8], frame_handles: &mut Handles) -> Option<Chunk> {
		let mut reader = Reader::with_handles(msg, frame_handles);
		let r = &mut reader;
		let _seq = r.u32()?;
		let value = Chunk::read(r)?;
		reader.finish()?;
		frame_handles.clear();
		Some(value)
	}

	fn transport_outcome(error: TransportError) -> Error {
		match error {
			// The request never left this process, so nothing happened and trying
			// again is safe - which is what `again` says.
			TransportError::SendRefused | TransportError::NoRoute => Error::Again,
			// It went out and no answer came back. The server may have acted before
			// it died or before the deadline; nobody knows, and `commit-uncertain` is
			// the answer `base.error` grew so a caller is not forced to guess.
			// The reply could not be held, or arrived and broke the framing rules. In
			// both the server ANSWERED, so it acted; this end simply cannot read what
			// it said, which is the same position as never hearing back.
			TransportError::PeerClosed | TransportError::ReceiveFailed | TransportError::TimedOut | TransportError::NoMemory | TransportError::Malformed => Error::CommitUncertain,
		}
	}

	pub struct Client<T: Transport> {
		transport: T,
		corr: u32,
		deadline: u64,
		last_error: Option<TransportError>,
	}

	impl<T: Transport> Client<T> {
		pub fn new(transport: T) -> Client<T> {
			Client { transport, corr: 0, deadline: 0, last_error: None }
		}
		pub fn with_deadline(transport: T, deadline: u64) -> Client<T> {
			Client { transport, corr: 0, deadline, last_error: None }
		}
		pub fn set_deadline(&mut self, deadline: u64) {
			self.deadline = deadline;
		}
		pub fn last_error(&self) -> Option<TransportError> {
			self.last_error
		}
		pub fn into_transport(self) -> T {
			self.transport
		}
		fn next_corr(&mut self) -> u32 {
			let c = self.corr;
			self.corr = self.corr.wrapping_add(1);
			c
		}
		pub fn protocol_info(&mut self) -> Option<(String, u32)> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(PROTOCOL_INFO_OP)?;
			w.u32(corr)?;
			// No parameter, so no capability: `into_inner` says so rather than this
			// line assuming it.
			let request = writer.into_inner()?;
			let mut reply_handles = Handles::new();
			let reply = self
				.transport
				.call(&request, &[], &mut reply_handles, self.deadline)
				.map_err(|e| {
					self.last_error = Some(e);
					e
				})
				.ok()?;
			if !reply_handles.is_empty() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			let mut reader = Reader::new(&reply);
			let r = &mut reader;
			if r.u32()? != corr {
				return None;
			}
			let package = r.string_lp()?;
			let version = r.u32()?;
			r.finish()?;
			Some((package, version))
		}
		pub fn send(&mut self, data: &crate::codec::Buffer) -> Option<Result<u32, Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_SEND)?;
			w.u32(corr)?;
			w.set_handle(data.handle)?;
			w.u64(data.len)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? { Ok(r.u32()?) } else { Err(Error::read(r)?) };
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
		pub fn recv(&mut self) -> Option<u64> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_RECV)?;
			w.u32(corr)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = self
				.transport
				.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline)
				.map_err(|e| {
					self.last_error = Some(e);
					e
				})
				.ok()?;
			let mut reader = Reader::new(&reply);
			let r = &mut reader;
			if r.u32()? != corr || r.finish().is_none() || reply_handles.len() != 1 {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			Some(reply_handles.first())
		}
		pub fn close(&mut self) -> Option<Result<(), Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_CLOSE)?;
			w.u32(corr)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? { Ok(()) } else { Err(Error::read(r)?) };
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
	}

	#[cfg(feature = "channel-client-impl")]
	#[inline(never)]
	#[unsafe(export_name = "liber_channel_impl_liber_network_socket_send")]
	fn channel_invoke_send(chan: u64, data: &crate::codec::Buffer) -> Option<Result<u32, Error>> {
		let mut client = Client::new(ipc_client::ChannelTransport { chan });
		client.send(data)
	}

	#[cfg(feature = "channel-client-impl")]
	#[inline(never)]
	#[unsafe(export_name = "liber_channel_impl_liber_network_socket_recv")]
	fn channel_invoke_recv(chan: u64) -> Option<u64> {
		let mut client = Client::new(ipc_client::ChannelTransport { chan });
		client.recv()
	}

	#[cfg(feature = "channel-client-impl")]
	#[inline(never)]
	#[unsafe(export_name = "liber_channel_impl_liber_network_socket_close")]
	fn channel_invoke_close(chan: u64) -> Option<Result<(), Error>> {
		let mut client = Client::new(ipc_client::ChannelTransport { chan });
		client.close()
	}
}

/// One chunk of received socket data, the element of the `socket.recv` stream.
#[derive(Clone, Debug, PartialEq)]
pub struct Chunk {
	pub data: Vec<u8>,
}

impl Chunk {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<Chunk> {
		let mut r = Reader::new(bytes);
		let value = Chunk::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<Chunk> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = Chunk::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		if self.data.len() > u16::MAX as usize {
			return None;
		}
		w.u16(self.data.len() as u16)?;
		for v62 in self.data.iter() {
			w.u8(*v62)?;
		}
		Some(())
	}
	pub fn read(r: &mut Reader) -> Option<Chunk> {
		let data = {
			let v63 = r.u16()? as usize;
			let v63 = (v63 <= 4096).then_some(v63)?;
			let mut v64 = Vec::new();
			v64.try_reserve_exact(v63).ok()?;
			for _ in 0..v63 {
				v64.push(r.u8()?);
			}
			v64
		};
		Some(Chunk { data })
	}
}

/// A listening socket from `network.listen`, served on the channel it hands back.
/// `accept` waits until an inbound connection completes its handshake, then hands it
/// back as a `socket` capability together with both endpoints - the passive-open
/// counterpart to `network.connect`. The server calls `accept` in a loop, each call
/// yielding the next connection.
// interface `listener` over a channel: opcodes, a Service trait + dispatch, and a Client.
pub mod listener {
	use super::*;
	use crate::codec::{Reader, Sink, SliceWriter, Transport, TransportError, VecWriter};
	use alloc::vec::Vec;

	pub const OP_ACCEPT: u16 = 1;

	pub trait Service {
		fn accept(&mut self) -> Result<AcceptResult, Error>;
	}

	pub fn dispatch<S: Service>(service: &mut S, request: &[u8], request_handles: &mut Handles, out: &mut [u8], reply_handles: &mut Handles) -> Option<usize> {
		let mut reader = Reader::with_handle_list(request, request_handles);
		let r = &mut reader;
		let op = r.u16()?;
		let corr = r.u32()?;
		let mut writer = SliceWriter::new(out);
		if op == PROTOCOL_INFO_OP {
			r.finish()?;
			request_handles.clear();
			let w = &mut writer;
			w.u32(corr)?;
			w.bytes_lp(b"liber:network")?;
			w.u32(1)?;
			match Handles::try_from_slice(writer.handles()) {
				Some(taken) => *reply_handles = taken,
				None => return None,
			}
			return Some(writer.pos());
		}
		match op {
			OP_ACCEPT => {
				r.finish()?;
				request_handles.clear();
				let result = service.accept();
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v65) => {
							w.u8(1)?;
							v65.write(w)?;
						}
						Err(v66) => {
							w.u8(0)?;
							v66.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			_ => return None,
		}
		match Handles::try_from_slice(writer.handles()) {
			Some(taken) => *reply_handles = taken,
			None => return None,
		}
		Some(writer.pos())
	}

	fn transport_outcome(error: TransportError) -> Error {
		match error {
			// The request never left this process, so nothing happened and trying
			// again is safe - which is what `again` says.
			TransportError::SendRefused | TransportError::NoRoute => Error::Again,
			// It went out and no answer came back. The server may have acted before
			// it died or before the deadline; nobody knows, and `commit-uncertain` is
			// the answer `base.error` grew so a caller is not forced to guess.
			// The reply could not be held, or arrived and broke the framing rules. In
			// both the server ANSWERED, so it acted; this end simply cannot read what
			// it said, which is the same position as never hearing back.
			TransportError::PeerClosed | TransportError::ReceiveFailed | TransportError::TimedOut | TransportError::NoMemory | TransportError::Malformed => Error::CommitUncertain,
		}
	}

	pub struct Client<T: Transport> {
		transport: T,
		corr: u32,
		deadline: u64,
		last_error: Option<TransportError>,
	}

	impl<T: Transport> Client<T> {
		pub fn new(transport: T) -> Client<T> {
			Client { transport, corr: 0, deadline: 0, last_error: None }
		}
		pub fn with_deadline(transport: T, deadline: u64) -> Client<T> {
			Client { transport, corr: 0, deadline, last_error: None }
		}
		pub fn set_deadline(&mut self, deadline: u64) {
			self.deadline = deadline;
		}
		pub fn last_error(&self) -> Option<TransportError> {
			self.last_error
		}
		pub fn into_transport(self) -> T {
			self.transport
		}
		fn next_corr(&mut self) -> u32 {
			let c = self.corr;
			self.corr = self.corr.wrapping_add(1);
			c
		}
		pub fn protocol_info(&mut self) -> Option<(String, u32)> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(PROTOCOL_INFO_OP)?;
			w.u32(corr)?;
			// No parameter, so no capability: `into_inner` says so rather than this
			// line assuming it.
			let request = writer.into_inner()?;
			let mut reply_handles = Handles::new();
			let reply = self
				.transport
				.call(&request, &[], &mut reply_handles, self.deadline)
				.map_err(|e| {
					self.last_error = Some(e);
					e
				})
				.ok()?;
			if !reply_handles.is_empty() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			let mut reader = Reader::new(&reply);
			let r = &mut reader;
			if r.u32()? != corr {
				return None;
			}
			let package = r.string_lp()?;
			let version = r.u32()?;
			r.finish()?;
			Some((package, version))
		}
		pub fn accept(&mut self) -> Option<Result<AcceptResult, Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_ACCEPT)?;
			w.u32(corr)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? { Ok(AcceptResult::read(r)?) } else { Err(Error::read(r)?) };
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
	}

	#[cfg(feature = "channel-client-impl")]
	#[inline(never)]
	#[unsafe(export_name = "liber_channel_impl_liber_network_listener_accept")]
	fn channel_invoke_accept(chan: u64) -> Option<Result<AcceptResult, Error>> {
		let mut client = Client::new(ipc_client::ChannelTransport { chan });
		client.accept()
	}
}

